import sys

def rotate(g):
    # 90度右回転
    h, w = len(g), len(g[0])
    return [''.join(g[h-1-r][c] for r in range(h)) for c in range(w)]

def flip(g):
    return [row[::-1] for row in g]

def canonicalize(g):
    forms = []
    cur = g
    for _ in range(4):
        forms.append(tuple(cur))
        forms.append(tuple(flip(cur)))
        cur = rotate(cur)
    return min(forms)

